import { DatabaseSync } from 'node:sqlite';
const db = new DatabaseSync('D:/project/DSH/legion/team-hub/team.db', { readOnly: false });
db.exec('PRAGMA busy_timeout=5000');

const tasks = [
  { id: 'T-045', tag: 'S1', wave: 1, deps: [] },
  { id: 'T-046', tag: 'S3', wave: 1, deps: [] },
  { id: 'T-047', tag: 'S2', wave: 2, deps: ['T-045'] },
  { id: 'T-048', tag: 'S4', wave: 2, deps: ['T-046'] },
  { id: 'T-049', tag: 'S5', wave: 3, deps: ['T-048', 'T-047'] },
  { id: 'T-050', tag: 'S6', wave: 3, deps: ['T-048'] },
  { id: 'T-051', tag: 'S7', wave: 4, deps: ['T-050', 'T-049'] },
  { id: 'T-052', tag: 'S8', wave: 5, deps: ['T-051'] },
  { id: 'T-053', tag: 'R-1', wave: 5, deps: [] },
];

const blocksMap = new Map(tasks.map(t => [t.id, []]));
for (const t of tasks) {
  for (const dep of t.deps) {
    if (!blocksMap.has(dep)) blocksMap.set(dep, []);
    blocksMap.get(dep).push(t.id);
  }
}

const nowIso = new Date().toISOString();

db.exec('BEGIN IMMEDIATE');
try {
  const upd = db.prepare('UPDATE tasks SET blockedBy = ?, blocks = ?, description = ?, version = version + 1, updatedAt = ? WHERE id = ?');
  const getDesc = db.prepare('SELECT description FROM tasks WHERE id = ?');
  for (const t of tasks) {
    const row = getDesc.get(t.id);
    let desc = row?.description ?? '';
    const firstLine = desc.split('\n')[0] || `${t.tag} task`;
    const waveLine = `娉㈡锛?{t.wave}`;
    desc = [firstLine, waveLine].join('\n');
    const blockedBy = JSON.stringify(t.deps);
    const blocks = JSON.stringify(blocksMap.get(t.id) ?? []);
    upd.run(blockedBy, blocks, desc, nowIso, t.id);
    console.log(`${t.id} ${t.tag} blockedBy=${blockedBy} blocks=${JSON.stringify(blocksMap.get(t.id))}`);
  }
  db.exec('COMMIT');
  console.log('committed');
} catch (e) {
  db.exec('ROLLBACK');
  console.error('rollback', e);
  process.exitCode = 1;
}
