{
  "name": "@dsh-external/dsh-scrum-board",
  "version": "0.0.1",
  "description": "鍐涘洟 Scrum 鐪嬫澘 UI 闈㈡澘锛氬湪 DSH webServer 涓婅嚜鎵樼 kanban.html + /api/* + SSE锛岄殢 DSH 鍚姩",
  "private": true,
  "type": "module",
  "main": "./lib/index.js",
  "types": "./lib/types/index.d.ts",
  "files": [
    "lib"
  ],
  "license": "BSD-3-Clause",
  "peerDependencies": {
    "@deepseek-ai/dsh-client-ui-slots": ">=0.0.1-rc <2",
    "@deepseek-ai/dsh-host-webserver": ">=0.0.1-rc <2",
    "cordis": ">=4.0.0-rc <5",
