/** 登记产物（worker 完成时写；看板详情据此预览 html / 链接文件）。kind: html|file|url */
artifact(args) {
  requireArgs(args, ['by', 'kind', 'path'])
  const id = requireId(args)
  const kind = args.kind
  if (!['html', 'file', 'url'].includes(kind)) throw new Error(`非法 kind ${kind}（html|file|url）`)
  const t = withLock({
    id,
    ifVersion: args.ifVersion,
    mutate(t) {
      if (!Array.isArray(t.artifacts)) t.artifacts = []
      t.artifacts.push({ kind, title: args.title ?? '', path: args.path, by: args.by, at: now() })
    },
  })
  printTask(t)
},

/** 建立任务依赖/父子关系（blockedBy/blocks 成环即拒绝，整条 link 原子） */
link(args) {
  const id = requireId(args)
  const t = transact(db => {
    const t = task(db, id)
    // t blocks b → b 依赖 t（边 b→t）：若 t 已（传递）依赖 b，则成环
    for (const b of args.blocks?.split(',') ?? []) {
      if (b.length === 0) continue
      if (b === id) throw new Error(`任务不能阻塞自身（${id}）`)
      task(db, b)
      if (dependsOn(db, t.id, b)) throw new Error(`依赖成环：${id} 已依赖 ${b}，不能再声明 ${id} 阻塞 ${b}`)

