  })

  it('内容变化 → version+1 且回 pending（需复审）', () => {
    const changed = mod.registerSkill({ ...SKILL, prompt: '禁止隐式 var，显式声明类型' })
    assert.equal(changed.version, 2)
    assert.equal(changed.status, 'pending')
