// ── R-3 内容通道（S3）…注释块
const ARTIFACT_CONTENT_LIMIT = 512 * 1024

export function resolveArtifactReadTarget(taskId, recordPath, root) {
  let norm = String(recordPath ?? '').split('\\').join('/').trim()
  if (norm.length === 0) return null
  const rootAbs = resolve(root).split('\\').join('/').replace(/\/+$/, '')
  const taskSeg = '.legion-worktrees/' + taskId
  // 绝对/相对路径识别（盘符或前导斜杠）
  const drive = norm.length >= 2 && /^[A-Za-z]/.test(norm.slice(0, 1)) && norm.slice(1, 2) === ':'
  const startsSlash = norm.startsWith('/')
  let rel = norm
  if (drive || startsSlash || norm.startsWith('./') || norm.startsWith('../')) {
    const wtTask = rootAbs + '/.legion-worktrees/' + taskId
    if (norm === wtTask || norm === rootAbs) return null
    if (norm.startsWith(wtTask + '/')) rel = taskSeg + norm.slice(wtTask.length)
    else if (norm.startsWith(rootAbs + '/')) rel = norm.slice(rootAbs.length + 1)
    else return { unsafe: true }
  }
  if (rel.startsWith('./')) rel = rel.slice(2)
  const segs = rel.split('/')
  for (let k = 0; k < segs.length; k += 1) {
    const s = segs[k]
    if (s === '..' || s.toLowerCase() === '.git' || (s.length >= 2 && /^[A-Za-z]/.test(s.slice(0, 1)) && s.slice(1, 2) === ':')) return { unsafe: true }
  }
  if (segs[0] === '.legion-worktrees' && segs[1] !== taskId) return { unsafe: true }
  rel = segs.join('/')
  let wtAbs = null
  let mainRel = rel
  if (rel.startsWith(taskSeg + '/')) { wtAbs = join(root, rel); mainRel = rel.slice(taskSeg.length + 1) }
  else { wtAbs = join(root, '.legion-worktrees', taskId, rel) }
  const mainAbs = join(root, mainRel)
  let abs = null
  let source = 'main'
  if (existsSafe(wtAbs)) { abs = wtAbs; source = 'worktree' }
  else if (existsSafe(mainAbs)) { abs = mainAbs; source = 'main' }
  else return null
  try {
    const realAbs = realpathSync(abs)
    const realRoot = realpathSync(resolve(root))
    if (realAbs !== realRoot && !realAbs.startsWith(realRoot + '/') && !realAbs.startsWith(realRoot + '\\')) return { unsafe: true }
  } catch { return null }
  return { rel: mainRel, source, abs }
}
