/** href 安全校验：返回 null 表示不安全 → 调用方按纯文本渲染。 */
export function safeHref(raw: string): string | null {
  const href = raw.trim()
  if (href === '' || href.startsWith('#') || href.startsWith('/') || href.startsWith('./') || href.startsWith('../')) return href
