import { readFileSync, writeFileSync, rmSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { createRequire } from 'node:module'
import { renderToString } from 'react-dom/server'
const here = dirname(fileURLToPath(import.meta.url))
const require = createRequire(import.meta.url)
const ts = require('typescript')
const react = require('react')
const src = readFileSync(join(here, '..', 'src', 'components', 'MarkdownDocView.tsx'), 'utf8')
const tmp = join(here, '.dbg-s4-render.mjs')
const out = ts.transpileModule(src, { compilerOptions: { module: ts.ModuleKind.ESNext, target: ts.ScriptTarget.ES2022, jsx: ts.JsxEmit.ReactJSX, esModuleInterop: true } })
writeFileSync(tmp, out.outputText, 'utf8')
const mod = await import(pathToFileURL(tmp).href)
const md = '**未闭合 与 ~~~未闭合删除和 [未闭合链接 与 *** 以及普通行混排'
const html = renderToString(react.createElement(mod.default, { content: md }))
console.log(html)
console.log('has **未闭合:', html.includes('**未闭合'))
console.log('has 普通行:', html.includes('普通行'))
rmSync(tmp, { force: true })

