33: const FENCE = new RegExp('^(' + MD_TICK + '{3,}|~{3,})\\s*([\\w+.-]*)\\s*$')
34: 
35: /** 行内语法扫描（code/bold/italic/strike/link）。未匹配字符按文本原样前进，绝不丢内容。 */
36: function inline(text: string): ReactNode[] {
37:   const out: ReactNode[] = []
38:   let cursor = 0
39:   while (cursor < text.length) {
40:     const rest = text.slice(cursor)
41:     const code = CODE_RE.exec(rest)
42:     if (code) { out.push(<code key={nextKey()}>{code[1]}</code>); cursor += code[0].length; continue }
43:     const bold = /^(\*\*|__)([\s\S]+?)\1/.exec(rest)
44:     if (bold) { out.push(<strong key={nextKey()}>{inline(bold[2])}</strong>); cursor += bold[0].length; continue }
45:     const strike = /^(~~)([\s\S]+?)\1/.exec(rest)
46:     if (strike) { out.push(<s key={nextKey()}>{inline(strike[2])}</s>); cursor += strike[0].length; continue }
47:     const link = /^\[([^\]\n]+)\]\(([^)\s]+)\)/.exec(rest)
48:     if (link) {
49:       const label = link[1].trim()
50:       const href = safeHref(link[2])
51:       if (href !== null) {
52:         const isHttp = href.startsWith('http://') || href.startsWith('https://')
53:         out.push(<a key={nextKey()} href={href} target={isHttp ? '_blank' : undefined} rel={isHttp ? 'noreferrer noopener' : undefined}>{label}</a>)
54:       } else {
55:         out.push(<span key={nextKey()}>{label}</span>) // javascript: 等协议 → 纯文本
56:       }
57:       cursor += link[0].length
58:       continue
59:     }
60:     const italic = /^([*_])(?!\s)([^*_\n]+?)(?<!\s)\1/.exec(rest)
61:     if (italic) { out.push(<em key={nextKey()}>{italic[2]}</em>); cursor += italic[0].length; continue }
62:     // 图片语法（子集外）→ 原样文本回退（不得解析出可点击链接或 img 标签）
63:     if (rest.startsWith('![')) {
64:       const img = /^!\[([^\]\n]*)\]\(([^)\s]+)\)/.exec(rest)
65:       if (img) { out.push(img[0]); cursor += img[0].length; continue }
66:     }
67:     // 纯文本按「连续文本段」推进（避免逐字符切分 text node）
68:     let runEnd = text.length
69:     for (let k = cursor + 1; k < text.length; k += 1) {
70:       const ch = text[k]
71:       if (ch === '*' || ch === '_' || ch === '~' || ch === '[' || ch === MD_TICK) { runEnd = k; break }
72:     }
73:     out.push(text.slice(cursor, runEnd))
74:     cursor = runEnd
75:   }
76:   return out
77: }
