35: /** 探测 team-hub v2 是否可达（2.5s 超时，不影响主流程）。 */
36: export async function probeHub(timeoutMs = 2500): Promise<boolean> {
37:   const ctrl = new AbortController()
38:   const timer = setTimeout(() => ctrl.abort(), timeoutMs)
39:   try {
40:     const res = await fetch(`${hubBase()}/api/config`, { signal: ctrl.signal })
41:     return res.ok
42:   } catch {
43:     return false
44:   } finally {
45:     clearTimeout(timer)
46:   }
47: }
