.cal-footnote.err { color: #ff9c9c; display: flex; align-items: center; justify-content: center; gap: 4px; flex-wrap: wrap; }

/* ---------- 产出文档直达区（S5：任务详情同屏预览登记文档）---------- */
.doc-list { display: flex; flex-direction: column; gap: 6px; }
.doc-item { border: 1px solid var(--line); border-radius: 8px; padding: 6px 10px; background: rgba(255,255,255,0.015); }
.doc-item.doc-newest { border-color: rgba(91,140,255,0.45); background: rgba(91,140,255,0.06); }
.doc-item-head { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.doc-badge { font-size: 9px; color: #fff; background: var(--blue, #5b8cff); border-radius: 999px; padding: 0 6px; line-height: 1.6; font-weight: 700; }
.doc-title { font-weight: 600; color: var(--text); font-size: 12.5px; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; }
.doc-by { font-size: 10.5px; color: var(--accent); background: rgba(91,140,255,0.1); border-radius: 4px; padding: 0 5px; line-height: 1.7; white-space: nowrap; }
.doc-at { font-size: 10px; color: var(--muted-2); font-variant-numeric: tabular-nums; white-space: nowrap; }
.doc-path { margin-top: 2px; font-size: 10px; color: var(--muted-2); word-break: break-all; }
.doc-path code { cursor: pointer; user-select: all; color: var(--muted); }
.doc-path code:hover { color: var(--accent); text-decoration: underline; }
.doc-preview { margin-top: 6px; border-top: 1px dashed var(--line); padding-top: 8px; }
.doc-loading { font-size: 11px; color: var(--muted-2); padding: 8px 2px; }
.doc-err { font-size: 11px; color: #ff9c9c; background: rgba(255,92,92,0.08); border: 1px solid rgba(255,92,92,0.28); border-radius: 6px; padding: 6px 10px; word-break: break-all; }
.doc-truncate { font-size: 10px; color: #ffd479; margin-top: 6px; }
.doc-empty { font-size: 11px; color: var(--muted-2); padding: 6px 2px; }
.doc-plain { margin: 0; padding: 10px; font-size: 12px; line-height: 1.8; background: rgba(0,0,0,0.25); border-radius: 6px; white-space: pre-wrap; word-break: break-word; max-height: 440px; overflow-y: auto; color: var(--text); }

