content.text:
1: #!/usr/bin/env node
2: /**
3:  * serve —— 军团看板本地/局域网服务（零依赖，node 内置 http/fs/child_process）。
4:  *
5:  * 读接口（GET）：
6:  *   /                  → kanban.html（实时模式：SSE + 轮询兜底；拖拽写回）
7:  *   /console.html      → 军团总指挥部（节点 + 任务实时总览，SSE + 轮询，零 Token）
8:  *   /board.json        → 看板数据快照
9:  *   /KANBAN.md         → 文本看板
10:  *   /api/board         → board.json 内容（轮询端点）
11:  *   /api/board/events  → SSE：board.json 变化时推送完整看板数据
12:  *   /api/activity         → 最近动态事件（守护生命周期流，JSON 数组，?limit=N）
13:  *   /api/activity/events  → SSE：activity.jsonl 追加时推送新事件
14:  *   /api/config        → { auth, host, port, pipeline, daemon, paused } 供页面探测是否需要令牌
15:  *   /api/missions      → 服务端任务集聚合视图（按角色泳道 + 进度；?scope= 在 v1 无分区恒返回全部）
16:  *
17:  * 写接口（POST，配置了 token 时要求携带令牌）：
18:  *   /api/create        → 新建任务（backlog）→ 自动 render + SSE 广播
19:  *   /api/transition    → 状态迁移（复用 taskctl 状态机/乐观锁/角色纪律）
20:  *   /api/comment       → 追加评论（承载退回反馈/需求变更）
21:  *   /api/pause         → 全局暂停：写 scrum/control.json {paused:true}，守护每轮扫单前读取并跳过
22:  *   /api/resume        → 全局继续：写 scrum/control.json {paused:false}
23:  *
24:  * 令牌携带方式（任选其一）：Authorization: Bearer <t> / x-dsh-token: <t> / ?token=<t>。
25:  * GET 保持开放：看板数据非机密；拖拽/下达等写操作必须带令牌。
26:  * 每次写成功后自动跑 render.mjs 刷新 board.json，fs watch 触发 SSE 广播全端。
27:  *
28:  * 用法：
29:  *   node legion/scrum/serve.mjs [--port 4820] [--host 127.0.0.1] [--token <t>]
30:  * 局域网共享：--host 0.0.0.0 --token <t>，手机/其他电脑访问 http://<本机IP>:4820
31:  * 环境变量：DSH_KANBAN_PORT / DSH_KANBAN_HOST / DSH_KANBAN_TOKEN
32:  */
33: import { createServer } from 'node:http'
34: import { spawn } from 'node:child_process'
35: import { readFile, readFileSync, watch, watchFile, writeFileSync } from 'node:fs'
36: import { dirname, extname, join, normalize, sep } from 'node:path'
37: import { fileURLToPath } from 'node:url'
38: 
39: const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
40: const SCRUM = join(ROOT, 'scrum')
41: const BOARD_FILE = join(SCRUM, 'board.json')
42: const ACTIVITY_FILE = join(SCRUM, 'activity.jsonl')
43: const PATCHES_DIR = join(SCRUM, 'patches')
44: const TASKCTL = join(SCRUM, 'taskctl.mjs')
45: const RENDER = join(SCRUM, 'render.mjs')
46: const CONTROL_FILE = join(SCRUM, 'control.json')
47: 
48: const args = process.argv.slice(2)
49: 
50: /** 读取 `--key value` 参数，缺省时回退 */
51: function flag(key, fallback) {
52:   const i = args.indexOf(key)
53:   return i >= 0 ? args[i + 1] : fallback
54: }
55: 
56: const port = Number(flag('--port', process.env.DSH_KANBAN_PORT ?? 4820))
57: const host = flag('--host', process.env.DSH_KANBAN_HOST ?? '127.0.0.1')
58: const token = flag('--token', process.env.DSH_KANBAN_TOKEN ?? '')
59: 
60: const MIME = {
61:   '.html': 'text/html; charset=utf-8',
62:   '.json': 'application/json; charset=utf-8',
63:   '.md': 'text/markdown; charset=utf-8',
64: }
65: 
66: /** 只允许 serve scrum 目录内的白名单静态文件，杜绝目录穿越 */
67: function safeStatic(pathname) {
68:   const allowed = new Set(['/kanban.html', '/console.html', '/board.json', '/KANBAN.md', '/'])
69:   const target = pathname === '/' ? '/kanban.html' : pathname
70:   if (!allowed.has(target)) return null
71:   return join(SCRUM, normalize(target).replace(/^[/\\]+/, ''))
72: }
73: 
74: /** SSE 客户端集合 */
75: const clients = new Set()
76: 
77: /** 读取 board.json 并把多行 JSON 转成 SSE 消息体（`data: ` 前缀 + 空行结尾） */
78: function payloadOf(data) {
79:   return `${String(data).split('\n').map(line => `data: ${line}`).join('\n')}\n\n`
80: }
81: 
82: /** 读 board.json 推给单个客户端 */
83: function sendTo(res) {
84:   readFile(BOARD_FILE, (err, data) => {
85:     if (!err) res.write(payloadOf(data))
86:   })
87: }
88: 
89: /** 读 board.json 推给所有 SSE 客户端（watch 事件防抖 100ms） */
90: let broadcastTimer = null
91: function broadcast() {
92:   clearTimeout(broadcastTimer)
93:   broadcastTimer = setTimeout(() => {
94:     readFile(BOARD_FILE, (err, data) => {
95:       if (err) return
96:       const payload = payloadOf(data)
97:       for (const res of clients) res.write(payload)
98:     })
99:   }, 100)
100: }
101: 
102: watch(BOARD_FILE, () => broadcast())
103: 
104: /** 动态（activity）SSE 客户端集合与已广播字节偏移（activity.jsonl 只追加） */
105: const activityClients = new Set()
106: let activityOffset = 0
107: 
108: /** 把若干行（每行一个 JSON 事件）推给单个动态 SSE 客户端 */
109: function sendActivityLines(res, lines) {
110:   for (const line of lines) res.write(`data: ${line}\n\n`)
111: }
112: 
113: /** 读取 activity.jsonl 自上次偏移后的完整新行，广播给所有动态 SSE 客户端 */
114: function broadcastActivity() {
115:   readFile(ACTIVITY_FILE, (err, buf) => {
116:     if (err) return
117:     const text = buf.toString('utf8')
118:     const delta = text.slice(activityOffset)
119:     const lastNewline = delta.lastIndexOf('\n')
120:     if (lastNewline === -1) return // 无完整新行（尾行未写完）
121:     const complete = delta.slice(0, lastNewline + 1)
122:     activityOffset += complete.length
123:     const lines = complete.split('\n').filter(l => l.length > 0)
124:     for (const res of activityClients) sendActivityLines(res, lines)
125:   })
126: }
127: 
128: // activity.jsonl 由守护追加（文件可能尚未创建），用 poll watchFile 处理不存在/截断
129: watchFile(ACTIVITY_FILE, { interval: 1000 }, (curr, prev) => {
130:   if (curr.size < prev.size) activityOffset = 0 // 文件被截断/轮转
131:   if (curr.size !== prev.size) broadcastActivity()
132: })
133: 
134: /**
135:  * 以子进程方式执行 taskctl 命令（唯一变更入口，保证状态机/乐观锁/角色纪律一致）。
136:  * @param {string[]} argv - taskctl 子命令与参数，如 ['transition', 'T-001', '--to', 'done', '--by', 'general']
137:  * @returns {Promise<object>} 成功时 taskctl stdout 的 JSON（通常是任务对象）
138:  */
139: function runTaskctl(argv) {
140:   return new Promise((resolve, reject) => {
141:     const proc = spawn(process.execPath, [TASKCTL, ...argv], { cwd: ROOT })
142:     let out = ''
143:     let err = ''
144:     proc.stdout.on('data', d => { out += d })
145:     proc.stderr.on('data', d => { err += d })
146:     proc.on('error', e => reject(e))
147:     proc.on('close', code => {
148:       if (code === 0) {
149:         try {
150:           resolve(JSON.parse(out))
151:         } catch (e) {
152:           reject(new Error(`taskctl 输出不是 JSON：${out.slice(0, 200)}`))
153:         }
154:       } else {
155:         reject(new Error(err.trim() || `taskctl 退出码 ${code}`))
156:       }
157:     })
158:   })
159: }
160: 
161: /** 每次写成功后重跑 render.mjs，刷新 board.json / KANBAN.md / kanban.html（watch 触发 SSE 广播） */
162: function runRender() {
163:   return new Promise((resolve, reject) => {
164:     const proc = spawn(process.execPath, [RENDER], { cwd: ROOT })
165:     let err = ''
166:     proc.stderr.on('data', d => { err += d })
167:     proc.on('error', e => reject(e))
168:     proc.on('close', code => {
169:       if (code === 0) resolve()
170:       else reject(new Error(err.trim() || `render.mjs 退出码 ${code}`))
171:     })
172:   })
173: }
