192: /** 请求是否携带合法令牌（token 未配置时恒放行） */
193: function authorized(req) {
194:   if (!token) return true
195:   const url = new URL(req.url ?? '/', `http://${req.headers.host ?? host}`)
196:   const header = req.headers.authorization ?? ''
197:   const bearer = header.startsWith('Bearer ') ? header.slice(7) : ''
198:   const custom = req.headers['x-dsh-token']
199:   const query = url.searchParams.get('token')
200:   return bearer === token || custom === token || query === token
201: }
202: 
203: /** 读取请求 JSON 体 */
204: function readBody(req) {
205:   return new Promise((resolve, reject) => {
206:     let raw = ''
207:     req.on('data', d => { raw += d })
208:     req.on('end', () => {
209:       try {
210:         resolve(raw.length === 0 ? {} : JSON.parse(raw))
211:       } catch (e) {
212:         reject(new Error('请求体不是合法 JSON'))
213:       }
214:     })
215:     req.on('error', reject)
216:   })
217: }
