225: /**
226:  * 处理一次写操作：校验令牌 → 执行 taskctl → 重跑 render 刷新看板。
227:  * 乐观锁冲突映射为 409，其余业务错误映射为 400。
228:  */
229: async function handleWrite(req, res, run) {
230:   if (!authorized(req)) {
231:     json(res, 401, { error: '缺少或错误的令牌（--token 已启用）；用 ?token=… 或 Authorization: Bearer … 携带' })
232:     return
233:   }
234:   try {
235:     const body = await readBody(req)
236:     const task = await run(body)
237:     await runRender()
238:     json(res, 200, { ok: true, task })
239:   } catch (e) {
240:     const message = String(e.message ?? e)
241:     const status = message.includes('乐观锁') ? 409 : 400
242:     json(res, status, { error: message })
243:   }
244: }
