/** 产物读取绝对路径白名单解析（R-4 S2，K4-B）：
 *  - 相对路径 → join(ARTIFACT_ROOT, rel)；任何 ../ 或 .git 段拒绝；
 *  - 盘符/UNC 绝对路径 → 仅当在 ARTIFACT_ROOT 之内（legacy 登记）；
 * 返回 { abs } 或 { error: '403'|... }
 */
function artifactAbsPath(rel) {
  const p = String(rel ?? '').replace(/^\.\/+/, '')
  const drive = /^[A-Za-z]:[\\/]/.test(p) || p.startsWith('/') || p.startsWith('\\\\')
  if (drive) {
    const n = normalize(p)
    const base = normalize(ARTIFACT_ROOT)
    if (n === base || n.startsWith(base + sep)) return n
    return null
  }
  const segs = p.split(/[\\/]+/).filter(Boolean)
  if (segs.includes('..') || segs.includes('.git')) return null
  return join(ARTIFACT_ROOT, ...segs)
}
